//! Machine-readable read API; the implementation shares MCP's permission checks.
use crate::data::TOOLS;
use axum::Json;
use serde_json::{Map, Value, json};
pub(crate) async fn schema() -> Json<Value> {
    let paths:Map<String,Value>=TOOLS.iter().map(|(name,description,scope)|(format!("/v1/agent/{name}"),json!({"get":{"operationId":name,"summary":description,"description":format!("Read-only. Required scope: {}. Identity and timezone come from the connection, never from query parameters.",if scope.is_empty(){"any granted category"}else{scope}),"security":[{"agentBearer":[]}],"parameters":[{"name":"from","in":"query","schema":{"type":"string","format":"date"},"description":"Inclusive local date. Defaults to the last 30 days within consent."},{"name":"to","in":"query","schema":{"type":"string","format":"date"},"description":"Inclusive local date, no later than today. Maximum range 90 days."}],"responses":{"200":{"description":"Canonical backend data; missing values stay null.","content":{"application/json":{"schema":{"$ref":"#/components/schemas/ReadResponse"}}}},"400":{"description":"Invalid date window or extra query parameters"},"401":{"description":"Invalid, expired or revoked agent credential"},"403":{"description":"Permission denied"},"429":{"description":"Rate or concurrency limit"}}}}))).collect();
    Json(
        json!({"openapi":"3.1.0","info":{"title":"Zoop agent read API","version":"1"},"paths":paths,"components":{"securitySchemes":{"agentBearer":{"type":"http","scheme":"bearer","description":"A dedicated access key or OAuth access token issued by this Zoop server. Never use a phone token."}},"schemas":{"ReadResponse":{"type":"object","required":["schema_version","generated_at","timezone","from","to","source","data"],"properties":{"schema_version":{"const":1},"generated_at":{"type":"string","format":"date-time","description":"Response creation time, not the age of measurements."},"timezone":{"type":"string"},"from":{"type":"string","format":"date"},"to":{"type":"string","format":"date"},"source":{"const":"zoop_backend"},"data":{"type":"object","description":"Tool-specific readings, filtered by granted category. Use metric_definitions for units and interpretation."}}}}}}),
    )
}
